diff --git a/Sebastiaanschool/src/main/java/nl/sebastiaanschool/contact/app/data/DownloadManagerInterface.java b/Sebastiaanschool/src/main/java/nl/sebastiaanschool/contact/app/data/DownloadManagerInterface.java
